import net from 'node:net';

function raw(method, path, timeoutMs = 8000) {
  return new Promise((resolve) => {
    const chunks = [];
    const s = net.connect(9099, '127.0.0.1');
    const started = Date.now();
    let done = false;
    const finish = (how) => {
      if (done) return; done = true;
      s.destroy();
      resolve({ how, ms: Date.now() - started, bytes: Buffer.concat(chunks).toString('utf8') });
    };
    s.on('connect', () => {
      s.write(`${method} ${path} HTTP/1.1\r\nHost: 127.0.0.1:9099\r\nConnection: close\r\n\r\n`);
    });
    s.on('data', (c) => chunks.push(c));
    s.on('end', () => finish('server closed the connection'));
    s.on('error', (e) => finish('socket error: ' + e.message));
    setTimeout(() => finish(`STILL OPEN after ${timeoutMs} ms`), timeoutMs);
  });
}

for (const [method, path] of [['GET', '/health'], ['HEAD', '/health'], ['HEAD', '/nope'], ['OPTIONS', '/health']]) {
  const r = await raw(method, path);
  console.log(`\n=== ${method} ${path} -> ${r.how} after ${r.ms} ms, ${r.bytes.length} bytes`);
  console.log(JSON.stringify(r.bytes));
}
